<script setup lang="ts">
import { invoke } from "@tauri-apps/api/core";
import { computed, onMounted, ref } from "vue";
import { Plus, RefreshCw, Tags, X } from "lucide-vue-next";
import PaginationControls from "../components/PaginationControls.vue";
interface Category { id: number; name: string; description: string | null; product_count: number }
const categories = ref<Category[]>([]); const page = ref(1); const pageSize = 8; const name = ref(""); const description = ref(""); const editingId = ref<number | null>(null); const loading = ref(true); const saving = ref(false); const error = ref("");
const pagedCategories = computed(() => categories.value.slice((page.value - 1) * pageSize, page.value * pageSize));
async function load() { loading.value = true; error.value = ""; try { categories.value = await invoke<Category[]>("list_categories"); page.value = 1; } catch (e) { error.value = String(e); } finally { loading.value = false; } }
function edit(category: Category) { editingId.value = category.id; name.value = category.name; description.value = category.description ?? ""; }
function cancelEdit() { editingId.value = null; name.value = ""; description.value = ""; }
async function save() { if (!name.value.trim()) { error.value = "Nama kategori wajib diisi."; return; } saving.value = true; error.value = ""; try { if (editingId.value) await invoke("update_category", { input: { id: editingId.value, name: name.value, description: description.value || null } }); else await invoke("create_category", { input: { name: name.value, description: description.value || null } }); cancelEdit(); await load(); } catch (e) { error.value = String(e); } finally { saving.value = false; } }
async function remove(category: Category) { if (!window.confirm(`Hapus kategori ${category.name}? Kategori yang masih digunakan tidak dapat dihapus.`)) return; try { await invoke("delete_category", { categoryId: category.id }); await load(); } catch (e) { error.value = String(e); } }
onMounted(load);
</script>

<template><section class="module-page"><div class="section-intro"><div><p class="eyebrow">Katalog</p><h2>Kelola kategori</h2><p class="intro-copy">Kategori membantu mengelompokkan produk untuk pencatatan dan laporan.</p></div><button class="secondary-button" type="button" @click="load"><RefreshCw :size="15" /> Segarkan</button></div><div class="content-columns"><form class="panel form-panel" @submit.prevent="save"><div class="panel-heading"><div><p class="eyebrow">{{ editingId ? "Perubahan" : "Data baru" }}</p><h3>{{ editingId ? "Edit kategori" : "Tambah kategori" }}</h3></div><component :is="editingId ? X : Plus" :size="18" class="panel-icon" /></div><label>Nama kategori<input v-model="name" placeholder="Contoh: Keripik" /></label><label>Deskripsi <span class="optional">opsional</span><textarea v-model="description" rows="4"></textarea></label><p v-if="error" class="form-error">{{ error }}</p><div class="action-row"><button class="primary-button" :disabled="saving" type="submit">{{ saving ? "Menyimpan..." : editingId ? "Simpan perubahan" : "Simpan kategori" }}</button><button v-if="editingId" class="secondary-button" type="button" @click="cancelEdit">Batal</button></div></form><section class="panel table-panel paginated-panel"><div class="panel-heading"><div><p class="eyebrow">Daftar aktif</p><h3>Kategori</h3></div><span class="neutral-chip">{{ categories.length }} kategori</span></div><div v-if="loading" class="table-state">Memuat data...</div><div v-else-if="!categories.length" class="table-state"><Tags :size="22" /><strong>Belum ada kategori</strong><span>Tambahkan kategori untuk mulai membangun katalog.</span></div><template v-else><table><thead><tr><th>Nama</th><th>Deskripsi</th><th>Produk</th><th>Aksi</th></tr></thead><tbody><tr v-for="category in pagedCategories" :key="category.id"><td class="cell-strong">{{ category.name }}</td><td>{{ category.description || "—" }}</td><td>{{ category.product_count }}</td><td class="row-actions"><button type="button" @click="edit(category)">Edit</button><button type="button" @click="remove(category)">Hapus</button></td></tr></tbody></table><PaginationControls v-model:page="page" :total="categories.length" :page-size="pageSize" /></template></section></div></section></template>
